"""Recall questions for a checkpoint, generated by a program (no LLM) from the commands, outputs and
edits in the checkpoint prefix only; nothing from the hidden tests reaches them.

The diagnostic compares memory methods, so a fact is usable only if every call it rests on lies in the
steps they have written to memory at this checkpoint. All memory methods share MemoryPolicy's window
rule, which depends on token counts alone; `memory_window` replays it over every call of the prefix as
the online policy does (the window never moves back and gives way under the cap), so it equals the
`recent_start` of the replayed policies, which run_diag checks. Truncation and masking are references:
for them run_diag records whether each fact's sources survive in their context (`fact_visible`).
A question is dropped when its answer can be read off what every method sees: the pinned system/task
messages and the recent window (`visible` in make_questions).

Templates, each skipped when the prefix has no clean instance:
  reverted      files modified and clean again at the checkpoint (git checkout/restore, reset --hard, backup copy)
  test_latest   latest outcome of one test-runner invocation (same targets) run at least twice
  first_error   the first exception raised by a command that runs code
  edit_count    number of commands that tried to modify a file (failed attempts included), if >= 2
  membership    "did you display file X": up to 2 files displayed only in written steps (yes) and 2 files seen
                only in pure-search output (no); scored as hit / false-alarm rate, not pooled
  abstain       a file seen only in search output, never touched: gold "not in the history"; its false-alarm
                (hallucination) rate is reported apart from recall
"""
import hashlib
import json
import os
import re
import shlex

from flexamem.adapters.mswea import EARLIER_HEADER, RECENT_FRAC, RESERVE, TOOLS
from flexamem.bench.swe.checkpoints import call_cuts
from flexamem.llm.tokens import MSG_OVERHEAD, count, count_messages
from flexamem.memory.segmenter import parse_steps, swe_units

ABSTAIN = "not in the history"
TEMPLATES = ("reverted", "test_latest", "first_error", "edit_count", "membership", "abstain")
MEMBER_PER_SIDE = 2
_Q = r"""['"]"""
_PATH_TOKEN = re.compile(r"^[\w./-]+\.\w+$")
_SKIP_FILES = re.compile(r"(^|/)(patch\.txt|[^/]*\.(diff|patch|orig|bak|rej|pyc))$")
_SELECT_OPTS = {"-k", "-m", "--deselect", "--ignore"}  # options that change which tests run: part of the target
_VALUE_OPTS = {  # options whose next word is a value, not a test target
    "pytest": {"-k", "-m", "-p", "-c", "-o", "-W", "-n", "--deselect", "--ignore", "--rootdir", "--tb"},
    "django runtests.py": {"-v", "--verbosity", "--settings", "--parallel", "--start-at", "--start-after", "-k"},
    "django manage.py test": {"-v", "--verbosity", "--settings", "--parallel", "-k"},
    "python -m unittest": {"-k"}, "sympy bin/test": {"-k", "--seed", "--timeout"}}
_TB = "Traceback (most recent call last):"
_FRAME = re.compile(r'^\s*File "[^"]+", line \d+')
_EXC = re.compile(r"^(?:E\s+)?([A-Za-z_][\w.]*)(?::\s?(.*))?$")
_SEARCH = ("grep", "egrep", "fgrep", "rg", "find", "ls")
_FILTERS = ("head", "tail", "sort", "uniq", "wc", "cut")
_DISPLAY = ("cat", "head", "tail", "nl", "less", "more", "sed")
_HEREDOC = re.compile(r"<<(-?)\s*(['\"]?)(\w+)\2")


def _sha(text: str) -> str:
    return hashlib.sha1((text or "").encode()).hexdigest()[:16]


def _text(m: dict) -> str:
    c = m.get("content") or ""
    return c if isinstance(c, str) else "".join(p.get("text", "") for p in c if isinstance(p, dict))


def calls(messages: list[dict]) -> list[dict]:
    """Tool calls of the prefix in order: {step (1-based), call_id, command, output, rc}."""
    out = []
    for n, step in enumerate(parse_steps(messages[2:]), 1):
        outputs = {m.get("tool_call_id"): m.get("content") or "" for m in step if m.get("role") == "tool"}
        for tc in step[0].get("tool_calls") or []:
            try:
                cmd = json.loads(tc["function"]["arguments"]).get("command", "")
            except (json.JSONDecodeError, KeyError, TypeError, AttributeError):
                continue
            text = outputs.get(tc.get("id"), "")
            rc = re.search(r"<returncode>(-?\d+)</returncode>", text)
            out.append({"step": n, "call_id": tc.get("id"), "command": cmd, "output": text,
                        "rc": int(rc.group(1)) if rc else None})
    return out


def memory_window(messages: list[dict], budget: int) -> dict:
    """MemoryPolicy's recent window at the end of this prefix (see module doc): its first unit and the
    number of leading steps written to memory before it. When system + task leave no room under the cap
    the policy refuses to run, and nothing counts as written."""
    cap, rs = int(budget * RESERVE), 0
    pin_tok = count_messages(messages[:2], TOOLS)
    overhead = MSG_OVERHEAD + count(EARLIER_HEADER) + 2
    n_steps = len(parse_steps(messages[2:]))
    if pin_tok + overhead >= cap:
        return {"recent_start": 0, "steps": 0, "n_steps": n_steps}
    for c in call_cuts(messages) + [len(messages)]:
        if count_messages(messages[:c], TOOLS) <= cap:
            continue
        units = swe_units(parse_steps(messages[2:c]))
        if not units:
            continue
        start, tok = len(units) - 1, units[-1].msg_tokens
        while start > rs and tok + units[start - 1].msg_tokens <= int(RECENT_FRAC * budget):
            start -= 1
            tok += units[start].msg_tokens
        while start < len(units) - 1 and pin_tok + tok + overhead > cap:
            tok -= units[start].msg_tokens
            start += 1
        rs = start
    units = swe_units(parse_steps(messages[2:]))
    return {"recent_start": rs, "steps": sum(len(parse_steps(u.messages)) for u in units[:rs]), "n_steps": n_steps}


def fact_visible(q: dict, ctx: list[dict]) -> bool:
    """Whether every source of the fact is in a rendered context unchanged: an output as its original
    tool message, a command as the assistant message that issued it."""
    outs = {m.get("tool_call_id"): _sha(m.get("content")) for m in ctx if m.get("role") == "tool"}
    issued = {tc.get("id") for m in ctx if m.get("role") == "assistant" for tc in m.get("tool_calls") or []}
    return all(s["call_id"] in issued if s["kind"] == "command" else outs.get(s["call_id"]) == s["sha"]
               for s in q["sources"])


# ---- shell parsing ------------------------------------------------------------------------------------------

def _statements(cmd: str) -> list[list[str]]:
    """Simple commands in execution order as [text, heredoc bodies, operator after]: split at &&, ||, ;, |, &
    and newlines outside quotes; comments dropped; a heredoc body stays with the command that opened it.
    Unbalanced quotes give the whole command as one statement."""
    out, cur, pending, i, q, n = [], [], [], 0, None, len(cmd)

    def flush(sep):
        text = "".join(cur).strip()
        cur.clear()
        if text:
            out.append([text, "", sep])
        elif out and sep != ";":
            out[-1][2] = sep

    while i < n:
        ch = cmd[i]
        if q:
            cur.append(ch)
            if ch == "\\" and q == '"' and i + 1 < n:
                cur.append(cmd[i + 1])
                i += 1
            elif ch == q:
                q = None
            i += 1
        elif ch in "'\"":
            q = ch
            cur.append(ch)
            i += 1
        elif ch == "\\" and i + 1 < n:
            cur.append(" " if cmd[i + 1] == "\n" else cmd[i:i + 2])
            i += 2
        elif ch == "#" and (i == 0 or cmd[i - 1] in " \t\n;&|("):
            i = cmd.find("\n", i) if "\n" in cmd[i:] else n
        elif m := _HEREDOC.match(cmd, i):
            pending.append((m.group(3), m.group(1) == "-", len(out)))
            cur.append(m.group(0))
            i = m.end()
        elif ch == "\n":
            flush(";")
            i += 1
            for word, dash, k in pending:  # bodies follow the line that opened them
                body = []
                while i < n:
                    e = cmd.find("\n", i)
                    e = n if e < 0 else e
                    line, i = cmd[i:e], e + 1
                    if (line.strip() if dash else line.rstrip()) == word:
                        break
                    body.append(line)
                if k < len(out):
                    out[k][1] += "\n".join(body) + "\n"
            pending.clear()
        elif cmd[i:i + 2] in ("&&", "||"):
            flush(cmd[i:i + 2])
            i += 2
        elif ch in ";|" or (ch == "&" and cmd[i - 1:i] not in (">", "<") and cmd[i + 1:i + 2] != ">"):
            flush(ch)
            i += 1
        else:
            cur.append(ch)
            i += 1
    flush("")
    return [[cmd, "", ""]] if q else out


def _words(text: str) -> list[str]:
    try:
        return shlex.split(text)
    except ValueError:
        return []


def _cd(cwd: str | None, w: list[str]) -> str | None:
    """Directory after `cd` relative to /testbed ("" for the root), None outside the repository."""
    if len(w) < 2 or w[1] in ("-", "~") or w[1].startswith("$"):
        return None
    if cwd is None and not w[1].startswith("/"):
        return None
    p = os.path.normpath(w[1] if w[1].startswith("/") else os.path.join("/testbed", cwd, w[1]))
    return "" if p == "/testbed" else p[len("/testbed/"):] if p.startswith("/testbed/") else None


def _walk(cmd: str):
    """(words, text, body, operator before, operator after, cwd) of each statement; commands start in /testbed."""
    cwd, prev = "", ""
    for text, body, sep in _statements(cmd):
        w = _words(text)
        while w and re.match(r"^\w+=", w[0]):
            w = w[1:]
        if w and w[0] == "cd":
            cwd = _cd(cwd, w)
        elif w:
            yield w, text, body, prev, sep, cwd
        prev = sep


def _repo(cwd: str | None, p: str) -> str | None:
    """p (used in directory cwd) as a repository path relative to /testbed, or None."""
    p = p.strip().strip("'\"`")
    if cwd is None or not p or p.startswith(("~", "-")) or "$" in p or "*" in p:
        return None
    p = os.path.normpath(p if p.startswith("/") else os.path.join("/testbed", cwd, p))
    if not p.startswith("/testbed/"):
        return None
    p = p[len("/testbed/"):]
    return p if _PATH_TOKEN.match(p) and not _SKIP_FILES.search(p) else None


def _norm_path(p: str) -> str | None:
    return _repo("", p)


def _operands(w: list[str], value_opts=()) -> list[str]:
    """Words after the program that are neither options, option values nor redirections."""
    out, skip = [], False
    for i, x in enumerate(w[1:], 1):
        if skip or x.startswith("-") or w[i - 1] in value_opts or re.match(r"^\d*(&?>|<)", x):
            skip = bool(re.fullmatch(r"\d*(&?>>?|<<?)&?", x))  # a bare operator: its target is the next word
            continue
        out.append(x)
    return out


def _edits(w: list[str], text: str, body: str, cwd) -> list[str]:
    s = text + "\n" + body
    found = re.findall(r"^\*\*\* (?:Update|Add|Delete) File: (\S+)", s, re.M)
    if re.search(r"\bgit\s+apply\b|\bpatch\b", text):
        found += re.findall(r"^\+\+\+ b/(\S+)", s, re.M)
    found += re.findall(rf"Path\(\s*{_Q}([^'\"]+){_Q}\s*\)\.write_(?:text|bytes)\(", s)
    found += re.findall(rf"open\(\s*{_Q}([^'\"]+){_Q}\s*,\s*{_Q}[wa]", s)
    for var, p in re.findall(rf"(\w+)\s*=\s*(?:pathlib\.)?Path\(\s*{_Q}([^'\"]+){_Q}\s*\)", s):
        if re.search(rf"\b{var}\.write_(?:text|bytes)\(|open\(\s*{var}\s*,\s*{_Q}[wa]", s):
            found.append(p)
    for var, p in re.findall(rf"(\w+)\s*=\s*{_Q}([^'\"]+\.\w+){_Q}", s):
        if re.search(rf"open\(\s*{var}\s*,\s*{_Q}[wa]|Path\(\s*{var}\s*\)\.write_(?:text|bytes)\(", s):
            found.append(p)
    if w[0] in ("cat", "echo", "printf"):
        found += re.findall(r">>?\s*['\"]?([^\s'\"<>|;&]+)", re.sub(_HEREDOC, "", text))
    if w[0] in ("sed", "perl") and any(x.startswith(("-i", "--in-place")) or (w[0] == "perl" and re.match(r"^-\w*i", x))
                                      for x in w[1:]):
        ops = _operands(w, {"-e"})
        found += ops if "-e" in w else ops[1:]  # without -e the first operand is the script
    elif w[0] == "tee":
        found += _operands(w)
    return [q for q in (_repo(cwd, x) for x in found) if q]


def file_events(cmd: str) -> list[tuple[str, str]]:
    """What a command does to repository files, in execution order: ("edit", path), ("revert", path), or
    ("revert_all", dir prefix) for `git checkout .` / `git reset --hard`, expanded by the caller."""
    out = []
    for w, text, body, _, _, cwd in _walk(cmd):
        if cwd is None:
            continue
        if w[:2] == ["git", "checkout"] or (w[:2] == ["git", "restore"]
                                            and ("--staged" not in w or "--worktree" in w)):
            args = [x for x in w[2:] if not x.startswith("-") and x != "HEAD"]
            if "." in args:
                out.append(("revert_all", cwd and cwd + "/"))
            else:
                out += [("revert", q) for q in (_repo(cwd, x) for x in args) if q]
        elif w[:3] == ["git", "reset", "--hard"]:
            out.append(("revert_all", ""))
        elif w[0] in ("cp", "mv") and len(w) >= 3 and re.search(r"\.(orig|bak)$", w[-2]) and w[-2].startswith(w[-1]):
            if q := _repo(cwd, w[-1]):
                out.append(("revert", q))
        else:
            out += [("edit", q) for q in _edits(w, text, body, cwd)]
    return out


def displayed_files(cmd: str) -> list[str]:
    """Files whose contents the command prints: cat/head/tail/nl/less or `sed -n` with a file operand, unless
    piped into something other than another display command."""
    st, out = list(_walk(cmd)), []
    for k, (w, _, _, _, sep, cwd) in enumerate(st):
        if w[0] not in _DISPLAY or (w[0] == "sed" and ("-n" not in w
                                                     or any(x.startswith(("-i", "--in-place")) for x in w))):
            continue
        if sep == "|" and (k + 1 == len(st) or st[k + 1][0][0] not in _DISPLAY):
            continue
        ops = _operands(w, {"-n", "-c"} if w[0] in ("head", "tail") else {"-e"} if w[0] == "sed" else ())
        ops = ops[1:] if w[0] == "sed" and "-e" not in w else ops
        out += [q for q in (_repo(cwd, x) for x in ops) if q]
    return out


def pure_search(cmd: str) -> bool:
    """grep / find (no -exec) / ls, optionally filtered by head/tail/sort/wc/cut in a pipe; no xargs or $(...)."""
    if re.search(r"-exec(dir)?\b|\bxargs\b|\$\(|`", cmd):
        return False
    st = list(_walk(cmd))
    return bool(st) and all(not body and (w[0] in _SEARCH or (w[0] in _FILTERS and prev == "|" and not
                            any(not re.match(r"^(-.*|\d+|\d*[<>].*)$", x) for x in w[1:])))
                            for w, _, body, prev, _, _ in st)


def _runs_code(cmd: str) -> bool:
    """Whether a command may raise a Python exception (not only cd, search or display)."""
    return any(w[0] not in _SEARCH + _FILTERS + _DISPLAY + ("echo", "git") for w, *_ in _walk(cmd))


# ---- tests ---------------------------------------------------------------------------------------------------

def _resolve(cwd: str, p: str) -> str:
    """A path relative to /testbed (or absolute outside it), given the cd directory."""
    p = p if p.startswith("/") else os.path.join("/testbed", cwd or "", p)
    p = os.path.normpath(p)
    return p[len("/testbed/"):] if p.startswith("/testbed/") else p


def _invocation(w: list[str], cwd: str) -> tuple | None:
    """(runner, targets) of a test-runner command, None for anything else. Targets are kept whole (node ids,
    dotted labels, test-selecting options) so that two invocations match only if they run the same tests."""
    while w and (re.match(r"^\w+=", w[0]) or w[0] in ("time", "env", "timeout")):
        w = w[2:] if w[0] == "timeout" else w[1:]
    if not w:
        return None
    prog, args = w[0], w[1:]
    if re.fullmatch(r"python[\d.]*", prog.rsplit("/", 1)[-1]):
        if args[:2] in (["-m", "pytest"], ["-m", "py.test"]):
            prog, args = "pytest", args[2:]
        elif args[:2] == ["-m", "unittest"]:
            prog, args = "unittest", args[2:]
        elif args[:3] == ["-m", "django", "test"]:
            prog, args = "manage.py", ["test"] + args[3:]
        else:
            prog = next((a for a in args if not a.startswith("-")), "")
            args = args[args.index(prog) + 1:] if prog else []
    prog = "bin/test" if prog.endswith("bin/test") else prog.rsplit("/", 1)[-1]
    if prog == "manage.py" and args[:1] == ["test"]:
        runner, args = "django manage.py test", args[1:]
    else:
        runner = {"pytest": "pytest", "py.test": "pytest", "runtests.py": "django runtests.py", "tox": "tox",
                  "unittest": "python -m unittest", "bin/test": "sympy bin/test"}.get(prog)
    if runner is None:
        return None
    opts = _VALUE_OPTS.get(runner, ())
    sel = [f"{a}={args[i + 1]}" for i, a in enumerate(args[:-1]) if a in _SELECT_OPTS]
    pos = _operands([prog] + args, opts)
    if runner == "pytest":
        pos = [_resolve(cwd, a.split("::")[0]) + a[len(a.split("::")[0]):] for a in pos]
    elif runner in ("python -m unittest", "sympy bin/test"):
        pos = [_resolve(cwd, a) if a.endswith(".py") or "/" in a else a for a in pos]
    elif runner == "tox":
        pos = []
    return runner, tuple(sorted(set(pos))) + tuple(sel)


def test_invocation(cmd: str) -> tuple | None:
    """The test runs a command makes, as ((runner, targets), ...): pytest, python -m unittest, Django runtests.py /
    manage.py test, sympy bin/test, tox. Flags are ignored except test selectors; paths are resolved against the cd
    directory, so `cd /testbed && python -m pytest -q tests/a.py::T` and `pytest tests/a.py::T -x` are the same."""
    found = [inv for w, _, _, _, _, cwd in _walk(cmd) if cwd is not None and (inv := _invocation(w, cwd))]
    return tuple(found) or None


def test_outcome(output: str, rc: int | None) -> str | None:
    tail = output[-4000:]
    failed = re.search(r"\b[1-9]\d* (failed|errors?)\b|^FAILED\b|^ERROR\b", tail, re.M)
    passed = re.search(r"\b\d+ passed\b|^OK\b|tests finished: \d+ passed", tail, re.M)
    if failed or (rc not in (0, None)) or (not passed and _TB in tail):
        return "fail"
    return "pass" if passed else None


def first_exception(output: str) -> tuple[str, str] | None:
    """(qualified type, message) of the first exception in an output: the first unindented line after a
    traceback header or after a `File "...", line N` frame (parse errors print no header), or a pytest
    `E   Type: message` line, whichever comes first."""
    lines = output.splitlines()
    for i, line in enumerate(lines):
        if line.startswith(_TB) or _FRAME.match(line):
            for nxt in lines[i + 1:]:
                if nxt.strip() and not nxt[0].isspace():
                    m = _EXC.match(nxt)
                    if m and (m.group(1)[0].isupper() or "." in m.group(1)) and (
                            line.startswith(_TB) or re.search(r"(Error|Exception)$", m.group(1))):
                        return m.group(1), (m.group(2) or "").strip()[:200]
                    break
        elif line.startswith("E   "):
            m = _EXC.match(line)
            if m and re.search(r"(Error|Exception)$", m.group(1)):
                return m.group(1), (m.group(2) or "").strip()[:200]
    return None


def key_tokens(msg: str) -> tuple[list[str], int]:
    """Tokens of an exception message an answer must name, and how many: every quoted name (up to 3), else a
    majority of its words."""
    quoted = list(dict.fromkeys(t.lower() for t in re.findall(r"['\"]([^'\"\s]{1,80})['\"]", msg)))[:3]
    if quoted:
        return quoted, len(quoted)
    words = list(dict.fromkeys(t.lower() for t in re.findall(r"[A-Za-z_][\w.]{2,}", msg)))[:8]
    return words, len(words) // 2 + 1 if words else 0


# ---- questions -----------------------------------------------------------------------------------------------

def _seen_paths(text: str) -> set[str]:
    """Repository paths printed by grep/find/ls-style output."""
    body = re.sub(r"</?(returncode|output|warning)>", "\n", text)
    found = re.findall(r"^(?:\./|/testbed/)?([\w-]+(?:/[\w.-]+)+\.py)(?::|$)", body, re.M)
    return {q for q in map(_norm_path, found) if q}


def _src(c: dict, kind: str) -> dict:
    return {"step": c["step"], "call_id": c["call_id"], "kind": kind,
            "sha": _sha(c["output"]) if kind == "output" else None}


def _h(*parts) -> str:
    return hashlib.sha256("|".join(map(str, parts)).encode()).hexdigest()


def make_questions(cp_meta: dict, messages: list[dict]) -> list[dict]:
    """Questions for one checkpoint (see module doc)."""
    budget, cid = cp_meta["budget"], cp_meta["cid"]
    win = memory_window(messages, budget)
    limit = win["steps"]  # steps 1..limit are in every memory method's memory
    cs = calls(messages)
    old = [c for c in cs if c["step"] <= limit]
    # what every method sees: system + task and the recent window
    visible = "\n".join([_text(m) for m in messages[:2]]
                        + [_text(m) for s in parse_steps(messages[2:])[limit:] for m in s]
                        + [c["command"] for c in cs if c["step"] > limit])
    qs = []

    def add(template, question, gold, match, sources, qid=None, **extra):
        qs.append({"qid": f"{cid}#{qid or template}", "cid": cid, "iid": cp_meta["iid"], "label": cp_meta["label"],
                   "budget": budget, "template": template, "question": question, "gold": gold, "match": match,
                   "evidence_steps": sorted({s["step"] for s in sources}), "sources": sources, "window": win,
                   **extra})

    modified, hist, edits = {}, {}, {}  # path -> modified now; path -> [(event, call)]; path -> edit calls
    for c in cs:
        for kind, f in file_events(c["command"]):
            fs = sorted(p for p, m in modified.items() if m and p.startswith(f)) if kind == "revert_all" else [f]
            for p in fs:
                if kind != "edit" and (not modified.get(p) or f"pathspec '{p}'" in c["output"]):
                    continue  # restoring an unmodified file changes nothing; a failed checkout neither
                modified[p] = kind == "edit"
                hist.setdefault(p, []).append((kind, c))
                if kind == "edit" and c not in edits.setdefault(p, []):
                    edits[p].append(c)

    rev = [p for p in sorted(hist) if not modified[p] and hist[p][-1][1]["step"] <= limit]
    # git stash, or a patch applied from a file, changes files the commands do not name: file states are unknown
    opaque = any(re.search(r"\bgit\s+(stash|apply|am)\b|\bpatch\s", c["command"])
                 and not any(k == "edit" for k, _ in file_events(c["command"])) for c in cs)
    if rev and not opaque and not any(p in visible for p in rev):
        add("reverted", "Which files did you modify and later revert to their original content during this task, "
                        "so that they are unmodified now? List their paths relative to the repository root.",
            rev, "path_set", [_src(c, "command") for p in rev for _, c in hist[p]])

    runs = {}
    for c in cs:
        if inv := test_invocation(c["command"]):
            runs.setdefault(inv, []).append((c, test_outcome(c["output"], c["rc"])))
    cand = [(k, r) for k, r in runs.items() if len(r) >= 2 and r[-1][0]["step"] <= limit and r[-1][1]]
    if cand:
        k, r = max(cand, key=lambda kr: (len({o for _, o in kr[1]}) > 1, len(kr[1]), -kr[1][0][0]["step"], kr[0]))
        desc = "; ".join(f"{runner} {' '.join(t)}".strip() for runner, t in k)
        if len(desc) <= 300:
            add("test_latest", f"You ran `{desc}` {len(r)} times during this task (other flags may differ between "
                               f"runs). Did the most recent run pass or fail? Answer pass or fail.", r[-1][1],
                "passfail", [_src(r[-1][0], "output")], stale=[o for _, o in r[:-1]],
                runs=[c["step"] for c, _ in r], invocation=[list(x) for x in k])

    first = next(((c, e) for c in cs if _runs_code(c["command"]) and (e := first_exception(c["output"]))), None)
    if first and first[0]["step"] <= limit:
        c, (etype, msg) = first
        short = etype.split(".")[-1]
        toks, need = key_tokens(msg)
        seen_now = f"{short}: {msg}" in visible if msg else re.search(rf"\b{re.escape(short)}\b", visible)
        if not seen_now:
            add("first_error", "What was the first Python exception that appeared in a command output during this "
                               "task? Give its type and message.", f"{etype}: {msg}" if msg else etype, "exception",
                [_src(c, "output")], exception_type=short, key_tokens=toks, key_need=need)

    cand = [(f, s) for f, s in edits.items() if len(s) >= 2 and s[-1]["step"] <= limit]
    if cand:
        f, s = max(cand, key=lambda fs: (len(fs[1]), -fs[1][0]["step"], fs[0]))
        add("edit_count", f"How many separate commands tried to modify `{f}` during this task (count failed attempts "
                          f"too)? Answer with a single integer.", str(len(s)), "int", [_src(c, "command") for c in s])

    # file-read membership: displayed only in written steps (yes) vs seen only in pure-search output (no)
    shown, searched = {}, {}
    for c in cs:
        for p in displayed_files(c["command"]):
            if "No such file" not in c["output"]:
                shown.setdefault(p, []).append(c)
        if pure_search(c["command"]):
            for p in sorted(_seen_paths(c["output"])):
                searched.setdefault(p, []).append(c)
    other = [c for c in cs if not pure_search(c["command"])]
    commands = "\n".join(c["command"] for c in cs)
    other_out, other_cmd = "\n".join(c["output"] for c in other), "\n".join(c["command"] for c in other)
    pos = sorted((p for p, s in shown.items() if p.endswith(".py") and s[-1]["step"] <= limit and p not in edits
                  and p not in visible), key=lambda p: _h(cid, p))
    neg = sorted((p for p, s in searched.items() if s[0]["step"] <= limit and p not in visible and p not in shown
                  and p not in hist and p not in commands and p not in other_out
                  and p.rsplit("/", 1)[-1] not in other_cmd), key=lambda p: _h(cid, p))
    chosen = sorted([(p, "yes") for p in pos[:MEMBER_PER_SIDE]] + [(p, "no") for p in neg[:MEMBER_PER_SIDE]],
                    key=lambda pg: _h(cid, pg[0]))
    for i, (p, gold) in enumerate(chosen, 1):
        src = [c for c in (shown[p] if gold == "yes" else searched[p]) if c["step"] <= limit]
        add("membership", f"Did you display the contents of `{p}` during this task? Answer yes or no.", gold,
            "yesno", [_src(c, "output") for c in src], qid=f"membership{i}", path=p)

    rest = [p for p in neg if p not in neg[:MEMBER_PER_SIDE]]
    if rest:
        p = min(rest, key=lambda x: _h(cid, "abstain", x))
        add("abstain", f"What did you change in `{p}`?", ABSTAIN, "abstain",
            [_src(c, "output") for c in searched[p] if c["step"] <= limit],
            explanation=f"{p} appeared only in search output and was never opened, edited or run.")
    return qs


def write_frozen(path, questions: list[dict]) -> str:
    """Write the question file and return its sha256."""
    data = frozen_bytes(questions)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return hashlib.sha256(data).hexdigest()


def frozen_bytes(questions: list[dict]) -> bytes:
    return "".join(json.dumps(q, sort_keys=True) + "\n" for q in questions).encode()
